<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {changeProfileWidth} from '../domain/geometry';
import {useEditor} from '../stores/editor';import {billRows,billCsv} from '../masonry/bill';import {download} from '../storage/archive';import {clone} from '../domain/project';import type {MasonryResult} from '../domain/types';
const e=useEditor(),working=ref(false),result=ref<MasonryResult|null>(null),row=ref(0),selectedWall=ref('');let worker:Worker|undefined,timer:ReturnType<typeof setTimeout>,generation=0;
const rows=computed(()=>result.value?billRows(e.document,result.value):[]),wall=computed(()=>e.walls.find(w=>w.id===selectedWall.value)||e.walls[0]),pieces=computed(()=>result.value?.pieces.filter(p=>p.wallId===wall.value?.id)||[]),profiles=computed(()=>e.document.profiles.filter(m=>m.id===e.document.exteriorProfileId||m.id===e.document.interiorProfileId));
function calculate(){worker?.terminate();const ticket=++generation,project=clone(e.document);result.value=null;working.value=true;worker=new Worker(new URL('../workers/masonry.worker.ts',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(ticket!==generation||project.id!==e.document.id||project.revision!==e.document.revision)return;working.value=false;worker?.terminate();if(data.error)e.error=data.error;else result.value=data.result;};worker.onerror=event=>{working.value=false;e.error=event.message;worker?.terminate();};worker.postMessage(project);}
watch(()=>e.document,()=>{clearTimeout(timer);worker?.terminate();generation++;result.value=null;working.value=true;timer=setTimeout(calculate,200);},{immediate:true});onBeforeUnmount(()=>{clearTimeout(timer);worker?.terminate();generation++;});
function field(id:string,key:'width'|'length'|'height'|'horizontalJoint'|'verticalJoint'|'kerf',event:Event){const value=Number((event.target as HTMLInputElement).value);e.architectural('Параметры кладки',p=>{const m=p.profiles.find(m=>m.id===id)!;if(key==='width'){changeProfileWidth(p,id,value);return;}const old=m.length;m[key]=value;if(key==='length'){const base=m.stock.find(s=>Math.abs(s.length-old)<1e-6);if(base)base.length=value;}});}
function csv(){if(result.value)download(new Blob([billCsv(e.document,result.value)],{type:'text/csv;charset=utf-8'}),'Ведомость кладки.csv');}
function print(){window.print();}
</script>
<template><section class="masonry-panel"><div class="section-heading"><div><div class="eyebrow">Блоки и кирпичи</div><h2>Раскладка и ведомость</h2></div><button :disabled="!result" @click="csv">Скачать CSV</button><button :disabled="!result" @click="print">Печать</button></div>
<p class="hint">Проверяем геометрию рядов и расход изделий. Несущая способность, перемычки и армирование требуют отдельного расчёта. Перевязка кирпича здесь — геометрическое правило проекта (¼ длины), без заявления о нормативной сертификации.</p>
<details class="profile-editor"><summary>Типоразмеры, швы и доступные изделия</summary><div class="profile-grid"><fieldset v-for="m in profiles"><legend>{{m.name}} · {{m.width*1000}} мм</legend><label v-for="key in (['length','width','height','horizontalJoint','verticalJoint','kerf'] as const)">{{({width:'Толщина стены, м',length:'Длина блока, м',height:'Высота блока, м',horizontalJoint:'Горизонтальный шов, м',verticalJoint:'Вертикальный шов, м',kerf:'Ширина реза, м'})[key]}}<input type="number" step="0.001" :value="m[key]" :disabled="e.document.architectureLocked" @change="field(m.id,key,$event)"></label><label v-for="s in m.stock" class="check-label"><input type="checkbox" :checked="s.enabled" :disabled="e.document.architectureLocked" @change="e.architectural('Наличие изделия',p=>{p.profiles.find(v=>v.id===m.id)!.stock.find(v=>v.id===s.id)!.enabled=($event.target as HTMLInputElement).checked})">{{s.name}} · {{s.length}} м</label><p class="hint">Включайте удлинённое изделие только если оно действительно доступно для покупки.</p></fieldset></div></details>
<p v-if="working" role="status">Рассчитываем ряды…</p><template v-if="result"><p :class="result.complete?'success-banner':'error-banner'">{{result.complete?'Раскладка завершена':'Неполная раскладка — не использовать как полный заказ'}} · {{result.pieces.length}} деталей · {{Math.round(result.elapsedMs)}} мс</p><details v-if="result.issues.length" open><summary>Необходимо проверить: {{result.issues.length}}</summary><ul class="issue-list"><li v-for="issue in result.issues.slice(0,60)">{{issue.row!==undefined?'Ряд '+(issue.row+1)+': ':''}}{{issue.message}}</li></ul><p v-if="result.issues.length>60">Показаны первые 60 замечаний.</p></details>
<div v-if="wall" class="course-view"><label>Стена<select v-model="selectedWall"><option v-for="(w,i) in e.walls" :value="w.id">{{w.roomIds.length===2?'Внутренняя':'Наружная'}} {{i+1}} · {{w.length.toFixed(2)}} м</option></select></label><svg :viewBox="`-0.4 -0.2 ${wall.length+.8} ${e.document.height+.4}`" role="img" aria-label="Раскладка деталей по рядам"><g :transform="`translate(0 ${e.document.height}) scale(1 -1)`"><rect v-for="piece in pieces" :x="piece.start" :y="piece.y" :width="piece.length" :height="piece.height" :fill="piece.cut?'#cd9d68':piece.stockId.includes('long')?'#668d79':'#d7d4bf'" stroke="#faf9f3" stroke-width=".007"><title>{{piece.length.toFixed(3)}} × {{piece.height.toFixed(3)}} м · {{piece.cut?'рез':'целое изделие'}}</title></rect></g></svg><p class="hint">Бежевый — целый · зелёный — удлинённый · охра — деталь с резом. Пустые участки без проёмов означают нерешённую раскладку.</p></div>
<div class="table-scroll"><table><thead><tr><th>Стены / изделие</th><th>Исходных</th><th>Деталей</th><th>Объём, м³</th><th>Пригодные остатки, м</th><th>Отходы, м³</th></tr></thead><tbody><tr v-for="r in rows"><td>{{r.kind}} · {{r.material}}<small>{{r.sku}}</small></td><td>{{r.stockCount}}</td><td>{{r.pieces}}</td><td>{{r.volume.toFixed(3)}}</td><td>{{r.reusableLength.toFixed(3)}}</td><td>{{r.wasteVolume.toFixed(3)}}</td></tr></tbody></table></div></template></section></template>
